import fetchMock from 'fetch-mock'
import Manifest from '../src/Manifest'

describe('Auth', () => {
  const baseUrl: string = 'http://localhost:1111/api/auth'

  const credentials = {
    email: 'admin@manifest.build',
    password: 'admin'
  }
  const token: string = '12345'

  beforeEach(() => {
    fetchMock.restore()
  })

  it('should login', async () => {
    fetchMock.mock(
      {
        url: `${baseUrl}/users/login`,
        method: 'POST',
        body: credentials,
        headers: {
          'Content-Type': 'application/json'
        }
      },
      {
        token: token
      }
    )

    const manifest = new Manifest()
    const response = await manifest.login(
      'users',
      credentials.email,
      credentials.password
    )

    expect(response).toEqual({ token: token })
  })

  it('should add token to headers after login', async () => {
    fetchMock.mock(
      {
        url: `${baseUrl}/users/login`,
        method: 'POST',
        body: credentials,
        headers: {
          'Content-Type': 'application/json'
        }
      },
      {
        token: token
      }
    )

    const manifest = new Manifest()
    await manifest.login('users', credentials.email, credentials.password)

    expect(manifest['headers']['Authorization']).toEqual(`Bearer ${token}`)
  })

  it('should logout', async () => {
    const manifest = new Manifest()
    manifest['headers']['Authorization'] = `Bearer ${token}`

    manifest.logout()

    expect(manifest['headers']['Authorization']).toBeUndefined()
  })

  it('should sign up', async () => {
    fetchMock.mock(
      {
        url: `${baseUrl}/users/signup`,
        method: 'POST',
        body: credentials,
        headers: {
          'Content-Type': 'application/json'
        }
      },
      {
        token: token
      }
    )

    const manifest = new Manifest()
    const response = await manifest.signup(
      'users',
      credentials.email,
      credentials.password
    )

    expect(response).toEqual(true)
    expect(manifest['headers']['Authorization']).toEqual(`Bearer ${token}`)
  })

  it('should return the current user', async () => {
    fetchMock.mock(
      {
        url: `${baseUrl}/users/me`,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json'
        }
      },
      {
        email: credentials.email
      }
    )

    const manifest = new Manifest()
    manifest['headers']['Authorization'] = `Bearer ${token}`
    const response = await manifest.from('users').me()

    expect(response).toEqual({ email: credentials.email })
  })
})

import { Test, TestingModule } from '@nestjs/testing'
import { OpenApiAuthService } from '../services/open-api-auth.service'
import { AppManifest, EntityManifest } from '@repo/types'
import { SecuritySchemeObject } from '@nestjs/swagger/dist/interfaces/open-api-spec.interface'
import { ADMIN_ENTITY_MANIFEST } from '../../constants'

describe('OpenApiAuthService', () => {
  let service: OpenApiAuthService

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [OpenApiAuthService]
    }).compile()

    service = module.get<OpenApiAuthService>(OpenApiAuthService)
  })

  it('should be defined', () => {
    expect(service).toBeDefined()
  })

  it('should generate a security scheme for admin auth', () => {
    const appManifestWithoutEntities: AppManifest = {
      entities: {}
    } as AppManifest

    const securitySchemes: Record<string, SecuritySchemeObject> =
      service.getSecuritySchemes(appManifestWithoutEntities)

    expect(Object.keys(securitySchemes)).toHaveLength(1)
    expect(securitySchemes).toHaveProperty('Admin')
  })

  it('should generate a security scheme if entity is authenticable', () => {
    const appManifestWithAuthenticableEntity: AppManifest = {
      name: 'Test',
      entities: {
        user: {
          className: 'User',
          authenticable: true
        } as EntityManifest
      }
    }

    const securitySchemes: Record<string, SecuritySchemeObject> =
      service.getSecuritySchemes(appManifestWithAuthenticableEntity)

    expect(Object.keys(securitySchemes)).toHaveLength(2)
    expect(securitySchemes).toHaveProperty('User')
  })

  it('should not generate a security scheme if entity is not authenticable', () => {
    const appManifestWithNonAuthenticableEntity: AppManifest = {
      name: 'Test',
      entities: {
        user: {
          className: 'User'
        } as EntityManifest
      }
    }

    const securitySchemes: Record<string, SecuritySchemeObject> =
      service.getSecuritySchemes(appManifestWithNonAuthenticableEntity)

    expect(Object.keys(securitySchemes)).toHaveLength(1)
  })

  it('should generate auth paths for admins', () => {
    const appManifestWithoutEntities: AppManifest = {
      entities: {}
    } as AppManifest

    const paths = service.generateAuthPaths(appManifestWithoutEntities)

    expect(paths).toHaveProperty(`/auth/${ADMIN_ENTITY_MANIFEST.slug}/login`)
    expect(paths).toHaveProperty(`/auth/${ADMIN_ENTITY_MANIFEST.slug}/me`)
  })

  it('should generate auth paths for authenticable entities', () => {
    const appManifestWithAuthenticableEntity: AppManifest = {
      name: 'Test',
      entities: {
        user: {
          slug: 'users',
          className: 'User',
          authenticable: true,
          policies: {
            create: [{ access: 'public' }],
            read: [{ access: 'public' }],
            update: [{ access: 'public' }],
            delete: [{ access: 'public' }],
            signup: [{ access: 'public' }]
          }
        } as EntityManifest
      }
    }

    const paths = service.generateAuthPaths(appManifestWithAuthenticableEntity)

    expect(paths).toHaveProperty(
      `/auth/${appManifestWithAuthenticableEntity.entities.user.slug}/login`
    )
    expect(paths).toHaveProperty(
      `/auth/${appManifestWithAuthenticableEntity.entities.user.slug}/signup`
    )
    expect(paths).toHaveProperty(
      `/auth/${appManifestWithAuthenticableEntity.entities.user.slug}/me`
    )
  })

  it('should not generate signup path if signup policy is forbidden', () => {
    const appManifestWithForbiddenSignup: AppManifest = {
      name: 'Test',
      entities: {
        user: {
          slug: 'users',
          className: 'User',
          authenticable: true,
          policies: {
            signup: [{ access: 'forbidden' }]
          }
        } as EntityManifest
      }
    }

    const paths = service.generateAuthPaths(appManifestWithForbiddenSignup)

    expect(paths).not.toHaveProperty(
      `/auth/${appManifestWithForbiddenSignup.entities.user.slug}/signup`
    )
    expect(paths).not.toHaveProperty(
      `/auth/${ADMIN_ENTITY_MANIFEST.slug}/signup`
    )
  })

  it('should generate a "/me" path for authenticable entities with a reference to the entity schema', () => {
    const appManifestWithAuthenticableEntity: AppManifest = {
      name: 'Test',
      entities: {
        user: {
          slug: 'users',
          className: 'User',
          authenticable: true,
          policies: {
            create: [{ access: 'public' }],
            read: [{ access: 'public' }],
            update: [{ access: 'public' }],
            delete: [{ access: 'public' }],
            signup: [{ access: 'public' }]
          }
        } as EntityManifest
      }
    }

    const paths = service.generateAuthPaths(appManifestWithAuthenticableEntity)

    expect(paths).toHaveProperty(
      `/auth/${appManifestWithAuthenticableEntity.entities.user.slug}/me`
    )
    expect(
      paths[`/auth/${appManifestWithAuthenticableEntity.entities.user.slug}/me`]
        .get
    ).toHaveProperty('responses')
    expect(
      paths[`/auth/${appManifestWithAuthenticableEntity.entities.user.slug}/me`]
        .get.responses
    ).toHaveProperty('200')
    expect(
      paths[`/auth/${appManifestWithAuthenticableEntity.entities.user.slug}/me`]
        .get.responses['200']['content']['application/json'].schema
    ).toHaveProperty(
      '$ref',
      `#/components/schemas/${appManifestWithAuthenticableEntity.entities.user.className}`
    )
  })
})

